from collections import deque
def enclosed(g, bg, shape):
    h,w=len(g),len(g[0])
    see=[[False]*w for _ in range(h)]; q=deque()
    for i in range(h):
        for j in (0,w-1):
            if g[i][j]!=shape: q.append((i,j)); see[i][j]=True
    for j in range(w):
        for i in (0,h-1):
            if g[i][j]!=shape: q.append((i,j)); see[i][j]=True
    while q:
        i,j=q.popleft()
        for a,b in((i+1,j),(i-1,j),(i,j+1),(i,j-1)):
            if 0<=a<h and 0<=b<w and not see[a][b] and g[a][b]!=shape:
                see[a][b]=True; q.append((a,b))
    return [[4 if not see[i][j] and g[i][j]==bg else g[i][j] for j in range(w)] for i in range(h)]
